<?php
function prov_status(string $p): array {
    $r = q_one('SELECT status, message, checked_at FROM provider_status WHERE provider=?', [$p]);
    $conf = ['imgbb' => imgbb_configured(), 'brevo' => brevo_configured(), 'mediafire' => mediafire_configured(), 'streamable' => true][$p];
    if ($r) return [$r['status'], $r['message'] . ' (' . $r['checked_at'] . ' UTC)'];
    if ($p === 'streamable') return ['manual', 'Hanya URL/embed (API upload tidak ada)'];
    if ($p === 'mediafire' && !$conf) return ['manual', 'Mode tautan manual'];
    return [$conf ? 'configured' : 'unconfigured', $conf ? 'Kredensial ada, belum diuji' : 'Belum dikonfigurasi'];
}
layout_head('Overview', 'overview');
$cnt = function (string $t, string $extra = '') { return (int)q_val("SELECT COUNT(*) FROM `$t` WHERE deleted_at IS NULL $extra"); };
echo '<div class="grid">';
foreach ([['Proyek', $cnt('projects')], ['Skills', $cnt('skills')], ['Media', $cnt('media')], ['Published', $cnt('projects', "AND status='published'") + $cnt('skills', "AND status='published'") + $cnt('journey', "AND status='published'")], ['Draft', $cnt('projects', "AND status='draft'") + $cnt('skills', "AND status='draft'") + $cnt('journey', "AND status='draft'")], ['Pesan baru', $cnt('messages', "AND status='new'")]] as $s)
    echo '<div class="card stat"><b>' . $s[1] . '</b>' . e($s[0]) . '</div>';
try { $today=(int)q_val("SELECT COUNT(*) FROM site_visits WHERE visited_at>=UTC_DATE()"); $unique=(int)q_val("SELECT COUNT(DISTINCT ip_hash) FROM site_visits WHERE visited_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)"); $routes=q_all("SELECT path,COUNT(*) visits FROM site_visits WHERE visited_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) GROUP BY path ORDER BY visits DESC LIMIT 8"); $daily=q_all("SELECT DATE(visited_at) AS day,COUNT(*) AS visits FROM site_visits WHERE visited_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 14 DAY) GROUP BY DATE(visited_at) ORDER BY day ASC"); } catch(Throwable $e){$today=0;$unique=0;$routes=[];$daily=[];} echo '</div><div class="grid"><div class="card stat"><b>'.number_format($today).'</b>Kunjungan hari ini</div><div class="card stat"><b>'.number_format($unique).'</b>Pengunjung unik 30 hari</div></div><div class="card"><h2>Traffic 14 hari</h2><div class="traffic-chart">'; $max=1; foreach($daily as$r)$max=max($max,(int)$r['visits']); foreach($daily as$r){$height=(int)round(((int)$r['visits']/$max)*100);echo '<span style="flex:1;text-align:center"><i style="height:'.$height.'%" title="'.e($r['day']).': '.(int)$r['visits'].' kunjungan"></i><small>'.e(substr($r['day'],5)).'</small></span>';} if(!$daily)echo '<span class="muted">Belum ada kunjungan.</span>'; echo '</div></div><div class="card"><h2>Traffic halaman</h2>'; if(!$routes) echo '<div class="empty-state"><strong>Belum ada traffic</strong><p>Data akan muncul setelah pengunjung membuka website.</p></div>'; else{echo '<table><thead><tr><th>Halaman</th><th>Kunjungan 30 hari</th></tr></thead><tbody>';foreach($routes as$r)echo '<tr><td>'.e($r['path']).'</td><td>'.number_format((int)$r['visits']).'</td></tr>';echo '</tbody></table>';} echo '</div><div class="card"><h2>Status integrasi</h2><table><tr><th>Provider</th><th>Status</th><th>Keterangan</th></tr>';
foreach (['imgbb' => 'ImgBB (gambar)', 'streamable' => 'Streamable (video)', 'mediafire' => 'MediaFire (dokumen)', 'brevo' => 'Brevo (email)'] as $k => $l) { list($st, $msg) = prov_status($k); echo '<tr><td>' . e($l) . '</td><td><span class="pill ' . ($st === 'success' ? 'success' : ($st === 'failed' ? 'failed' : '')) . '">' . e($st) . '</span></td><td>' . e($msg) . '</td></tr>'; }
echo '</table><p class="muted">Uji koneksi ada di menu Tools. "configured" berarti kredensial terisi, bukan berarti sudah terbukti bekerja.</p></div><div class="card"><h2>Aktivitas terbaru</h2><table>';
foreach (q_all('SELECT action, detail, created_at FROM audit_log ORDER BY id DESC LIMIT 10') as $r) echo '<tr><td>' . e($r['created_at']) . '</td><td>' . e($r['action']) . '</td><td>' . e($r['detail']) . '</td></tr>';
echo '</table></div>'; layout_foot();
